#include <bits/stdc++.h>
using namespace std;

#define forr(i, a, b) for (int i = (a); i < (int)(b); i++)
#define forn(i, n) forr(i, 0, n)
#define dforr(i, a, b) for (int i = (int)(b) - 1; i >= (a); i--)
#define dforn(i, n) dforr(i, 0, n)
#define pb push_back

using ll = long long;

const int MAXN = 1000100;
const ll INF = (ll)1e18 + 5;

int criba[MAXN];
vector<int> P;

void BuildS() {
    for (int p = 2; p * p < MAXN; p++) {
        if (!criba[p]) {
            for (int i = p * p; i < MAXN; i += p)
                criba[i] = p;
        }
    }
    forr(i, 2, MAXN) {
        if (!criba[i]) P.pb(i);
    }
}

bool OFlow(ll a, ll b) {
    return a > LLONG_MAX / b;
}

ll ans;
vector<int> E;

void tryme() {
    ll act = 1;
    dforn(i, E.size()) {
        int p = P[i];
        forn(j, E[i] - 1) {
            if (OFlow(act, p)) return;
            act *= p;
        }
    }
    ans = min(ans, act);
}

void solve(int n, int lim) {
    if (n == 1) {
        tryme();
        return;
    }
    forr(d, 2, min(lim + 1, n + 1)) {
        if (n % d == 0) {
            E.pb(d);
            solve(n / d, d);
            E.pop_back();
        }
    }
}

int main() {
    BuildS();

    int n;
    while (scanf("%d", &n) == 1) {
        ans = INF;
        solve(n, 61);
        printf("%lld\n", ans);
    }

    return 0;
}

